 // Computes, on the calling thread, out[i] = in[0] + ... + in[i] for i < n, and
 // hist[b] = number of i < n with (in[i] & 255) == b for b < 256. Neither out nor
 // hist is zeroed by the caller. n is any size from 0 to 20'000'000; the sums
-// never overflow int64.
+// never overflow int64. Uses 8 private sub-histograms to reduce contention on hot bins.
 extern "C" void scan_and_histogram(const int64_t* in, int64_t* out, size_t n, uint64_t* hist) {
+    // Zero the main histogram
     for (int b = 0; b < 256; ++b) hist[b] = 0;
+    
+    if (n == 0) return;
+    
+    // 8 private sub-histograms of uint32_t to avoid contention
+    // Each sub-histogram has 256 bins
+    static constexpr int NUM_SUBS = 8;
+    static constexpr int SUB_SIZE = 256;
+    uint32_t subs[NUM_SUBS][SUB_SIZE];
+    
+    // Zero sub-histograms
+    for (int s = 0; s < NUM_SUBS; ++s) {
+        for (int b = 0; b < SUB_SIZE; ++b) {
+            subs[s][b] = 0;
+        }
+    }
+    
+    // Process in blocks to help with caching
+    // Block size chosen to fit in L1/L2 cache
+    static constexpr size_t BLOCK_SIZE = 4096;
+    
+    size_t i = 0;
     int64_t sum = 0;
-    for (size_t i = 0; i < n; ++i) {
-        sum += in[i];
-        out[i] = sum;
-        hist[in[i] & 255]++;
+    
+    // Process full blocks
+    while (i + BLOCK_SIZE <= n) {
+        // Unroll by 8
+        for (size_t j = 0; j < BLOCK_SIZE; j += 8) {
+            int64_t v0 = in[i+j];
+            int64_t v1 = in[i+j+1];
+            int64_t v2 = in[i+j+2];
+            int64_t v3 = in[i+j+3];
+            int64_t v4 = in[i+j+4];
+            int64_t v5 = in[i+j+5];
+            int64_t v6 = in[i+j+6];
+            int64_t v7 = in[i+j+7];
+            
+            sum += v0; out[i+j]   = sum;
+            sum += v1; out[i+j+1] = sum;
+            sum += v2; out[i+j+2] = sum;
+            sum += v3; out[i+j+3] = sum;
+            sum += v4; out[i+j+4] = sum;
+            sum += v5; out[i+j+5] = sum;
+            sum += v6; out[i+j+6] = sum;
+            sum += v7; out[i+j+7] = sum;
+            
+            // Update sub-histograms, distributing by index to reduce contention
+            subs[(i+j)   % NUM_SUBS][(uint8_t)v0]++;
+            subs[(i+j+1) % NUM_SUBS][(uint8_t)v1]++;
+            subs[(i+j+2) % NUM_SUBS][(uint8_t)v2]++;
+            subs[(i+j+3) % NUM_SUBS][(uint8_t)v3]++;
+            subs[(i+j+4) % NUM_SUBS][(uint8_t)v4]++;
+            subs[(i+j+5) % NUM_SUBS][(uint8_t)v5]++;
+            subs[(i+j+6) % NUM_SUBS][(uint8_t)v6]++;
+            subs[(i+j+7) % NUM_SUBS][(uint8_t)v7]++;
+        }
+        i += BLOCK_SIZE;
+    }
+    
+    // Process remaining elements
+    for (size_t j = i; j < n; ++j) {
+        int64_t v = in[j];
+        sum += v;
+        out[j] = sum;
+        subs[j % NUM_SUBS][(uint8_t)v]++;
+    }
+    
+    // Merge sub-histograms into main histogram
+    for (int b = 0; b < SUB_SIZE; ++b) {
+        uint64_t total = 0;
+        for (int s = 0; s < NUM_SUBS; ++s) {
+            total += subs[s][b];
+        }
+        hist[b] = total;
     }
 }
